'use strict';
// Personal values are editable from the same rows shown in the reference.
const personalBeforeInlineEditing=personalPage;personalPage=function(){const template=document.createElement('template');template.innerHTML=personalBeforeInlineEditing();const rows=template.content.querySelectorAll('.personal-row');['name','phone','email'].forEach((field,i)=>{if(rows[i]){rows[i].dataset.action='edit-personal-field';rows[i].dataset.field=field}});const photo=template.content.querySelector('.personal-photo');if(photo)photo.dataset.action='edit-personal-avatar';if(rows[4])rows[4].dataset.action='edit-personal-all';return template.innerHTML};surfaces.personal=personalPage;
function validatePersonal(key,value){const text=String(value||'').trim();if(key==='name'&&(!text||text.length>60))throw Error('Вкажіть ім’я до 60 символів');if(key==='phone'&&text&&!/^\+?[0-9][0-9 ()-]{7,28}$/.test(text))throw Error('Перевірте номер телефону');if(key==='email'&&text&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text))throw Error('Перевірте електронну пошту');return text}
actions['edit-personal-field']=button=>{const key=button.dataset.field,labels={name:'Як до вас звертатися?',phone:'Телефон',email:'Ваша ел. пошта'},types={name:'text',phone:'tel',email:'email'};if(!labels[key])return;modal(labels[key],field(labels[key],key,state[key]||'',types[key],`maxlength="${key==='name'?60:key==='phone'?30:100}" autocomplete="${key==='name'?'name':key==='phone'?'tel':'email'}" ${key==='name'?'required':''}`),f=>{state[key]=validatePersonal(key,f.get(key))});const input=$('#fields input');input?.focus();if(key!=='email')input?.select()};
actions['edit-personal-all']=()=>modal('Особисті дані',field('Як до вас звертатися?','name',state.name,'text','required maxlength="60" autocomplete="name"')+field('Телефон','phone',state.phone||'','tel','maxlength="30" autocomplete="tel"')+field('Ваша ел. пошта','email',state.email||'','email','maxlength="100" autocomplete="email"'),f=>{const values={};for(const key of ['name','phone','email'])values[key]=validatePersonal(key,f.get(key));Object.assign(state,values)});
actions['edit-personal-avatar']=()=>modal('Фото профілю',`${state.avatar?`<img class="profile-editor-avatar" src="${esc(state.avatar)}" alt="Поточне фото">`:''}<label for="profile-avatar-upload">Виберіть нове фото</label><input id="profile-avatar-upload" name="avatar" type="file" accept="image/jpeg,image/png,image/webp">${state.avatar?'<label class="profile-remove-avatar"><input type="checkbox" name="removeAvatar"> Прибрати поточне фото</label>':''}`,async f=>{const file=f.get('avatar');if(file?.size){const value=await imageData(file);if(!value)throw Error('Виберіть JPG, PNG або WebP');const image=new Image();image.src=value;await image.decode();state.avatar=value}else if(f.get('removeAvatar'))state.avatar=null;else throw Error('Виберіть нове фото')});
// The large card scrolls out naturally. Only a separate header thumbnail remains.
let naturalCardScrollCleanup=null;
bindCardCollapse=function(){naturalCardScrollCleanup?.();const card=$('.expanded-card'),toolbar=$('.card-close'),settings=$('.card-settings');if(!card||!toolbar)return;card.style.transform='';const mini=document.createElement('button');mini.type='button';mini.className='card-header-mini';mini.dataset.action='card-scroll-top';mini.setAttribute('aria-label','Повернутися до картки');mini.innerHTML=cardArtwork(activeCard());toolbar.append(mini);const update=()=>{if(route.page!=='card'||!card.isConnected){window.removeEventListener('scroll',update);return}card.style.transform='';const rect=card.getBoundingClientRect(),p=Math.max(0,Math.min(1,(110-rect.bottom)/40));mini.style.opacity=String(p);mini.style.pointerEvents=p>.5?'auto':'none';mini.inert=p===0;settings.classList.toggle('compact-card-view',p>.8);mini.classList.toggle('flipped',card.classList.contains('flipped'))};window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update,{passive:true});naturalCardScrollCleanup=()=>{window.removeEventListener('scroll',update);window.removeEventListener('resize',update);mini.remove();naturalCardScrollCleanup=null};update()};
actions['card-scroll-top']=()=>pageScrollTo({top:0,behavior:shouldReduceMotion()?'instant':'smooth'});
function cleanHistoryStack(){return '<span class="history-stack clean-history-stack" aria-hidden="true"><i class="stack-rear"></i><i class="stack-middle"></i><i class="stack-front"><b></b><em></em></i></span>'}
const historyBeforeCleanStack=historyPage;historyPage=function(){const template=document.createElement('template');template.innerHTML=historyBeforeCleanStack();const image=template.content.querySelector('.history-stack');if(image)image.outerHTML=cleanHistoryStack();return template.innerHTML};
// Installation uses the platform prompt or Safari's own Home Screen flow.
const settingsBeforeInstallAction=appSettingsPage;appSettingsPage=function(){return settingsBeforeInstallAction()+`<section class="native-group install-settings">${button('install','Додати на головний екран','device-mobile','Відкривати без адресного рядка')}</section>`};
install=async function(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(standalone){toast('Застосунок уже відкрито з головного екрана');return}if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();return}const ios=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);modal('На головний екран',`<div class="install-guide"><img src="icon.png" alt="mono макет"><h3>mono макет</h3>${ios?'<p>Відкрийте цей сайт у Safari.</p><ol><li>Натисніть «Поділитися».</li><li>Виберіть «На початковий екран».</li><li>Увімкніть «Відкривати як вебпрограму», якщо цей перемикач показується.</li><li>Натисніть «Додати» та запускайте застосунок із нового значка.</li></ol>':'<p>У меню браузера виберіть «Встановити застосунок» або «Додати на головний екран», потім відкривайте його з нового значка.</p>'}<p>При запуску з цього значка адресний рядок браузера не показується.</p></div>`,null)};actions.install=()=>install();
// A brief branded introduction is shared by generated and uploaded receipts.
let receiptIntroKey=null,receiptIntro=null;
function clearReceiptIntro(){if(!receiptIntro)return;receiptIntro.observer?.disconnect();clearTimeout(receiptIntro.timer);receiptIntro.loader?.remove();receiptIntro=null}
function showReceiptIntro(){if(adminMode||!['file','receipt'].includes(route.page)){clearReceiptIntro();receiptIntroKey=null;return}const key=route.page+'/'+route.id;if(receiptIntroKey===key)return;clearReceiptIntro();const screen=$('#screen'),stage=$('.receipt-fit')||$('.receipt-document-stage')||$('.receipt-page'),footer=$('.receipt-share-footer');if(!stage)return;receiptIntroKey=key;const loader=document.createElement('div');loader.className='mono-receipt-intro';loader.setAttribute('role','status');loader.setAttribute('aria-label','Відкриваємо квитанцію');loader.innerHTML='<span>m</span>';loader.style.top=($('.toolbar')?.offsetHeight||64)+'px';loader.style.bottom=(footer?.offsetHeight||100)+'px';screen.append(loader);const session={key,loader,start:performance.now(),observer:null,timer:null,checking:false};receiptIntro=session;const reveal=()=>{if(receiptIntro!==session||session.checking)return;const images=[...stage.querySelectorAll('img')];if(route.page==='file'&&!images.length&&stage.getAttribute('aria-busy')==='true')return;session.checking=true;Promise.all(images.map(img=>img.decode().catch(()=>{}))).then(()=>{if(receiptIntro!==session)return;session.timer=setTimeout(()=>{if(receiptIntro!==session)return;if(shouldReduceMotion()){clearReceiptIntro();return}loader.animate([{opacity:1},{opacity:0}],{duration:120,easing:'cubic-bezier(.23,1,.32,1)',fill:'both'}).finished.then(()=>{if(receiptIntro===session)clearReceiptIntro()}).catch(()=>{if(receiptIntro===session)clearReceiptIntro()})},Math.max(0,180-(performance.now()-session.start)))})};session.observer=new MutationObserver(reveal);session.observer.observe(stage,{childList:true,subtree:true,attributes:true,attributeFilter:['aria-busy']});reveal()}
const renderBeforeProfileAndPWA=render;render=function(){renderBeforeProfileAndPWA();if(route.page!=='card')naturalCardScrollCleanup?.();showReceiptIntro()};
render();
const measureBeforeHeaderThumbnail=measureCardPose;measureCardPose=function(el){if(el?.classList.contains('expanded-card')){const mini=$('.card-header-mini'),rect=el.getBoundingClientRect();if(mini&&rect.bottom<=110&&Number(getComputedStyle(mini).opacity)>.5){const pose=measureBeforeHeaderThumbnail(mini),painted=mini.querySelector('.bank-card').getBoundingClientRect();pose.rect=painted;pose.center={x:painted.x+painted.width/2,y:painted.y+painted.height/2};pose.sourceAngle=35;pose.flipped=mini.classList.contains('flipped');return pose}}return measureBeforeHeaderThumbnail(el)};
